typedef struct { float x, y, vx, vy; } Particle;
static Particle *pool;                  /* one allocation, values in a row */
static size_t active, capacity;
void step(float dt) {
    for (size_t i = 0; i < active; i++) {           /* no branch, no chase */
        pool[i].x += pool[i].vx * dt;
        pool[i].y += pool[i].vy * dt;
    }
}
void deactivate(size_t i) { pool[i] = pool[--active]; }  /* keep it packed */
